45	    public void Registrar(RegistroAuditoria r)
46	    {
47	        string linea;
48	        try
49	        {
50	            var llave = cfg["LLM_API_KEY"]?.Trim();
51	            string? Limpiar(string? s) =>
52	                s != null && !string.IsNullOrEmpty(llave) ? s.Replace(llave, "[REDACTADO]", StringComparison.Ordinal) : s;
53	
54	            var pregunta = Limpiar(r.Pregunta);
55	            if (pregunta is { Length: > MaxPregunta }) pregunta = pregunta[..MaxPregunta];
56	            linea = JsonSerializer.Serialize(new
57	            {
58	                fechaHora = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
59	                rol = Limpiar(r.Rol),
60	                id = Limpiar(r.Id),
