135	    (string Respuesta, IReadOnlyList<Cita> Citas) InterpretarCrudo(string? texto)
136	    {
137	        texto ??= "";
138	        // Acota el análisis: un texto enorme se devuelve crudo, sin citas.
139	        if (texto.Length > MaxAnalisis) return (texto, []);
140	        var limpio = texto.Trim();
141	        var m = Regex.Match(limpio, @"^```[a-zA-Z]*\s*(.*?)\s*```$", RegexOptions.Singleline);
142	        if (m.Success) limpio = m.Groups[1].Value;
143	        if (IntentarParsear(limpio) is { } ok) return ok;
144	
145	        var intentos = 0;
146	        for (var i = limpio.IndexOf('{'); i >= 0 && intentos++ < MaxCandidatos; i = limpio.IndexOf('{', i + 1))
