156	    static int FinObjeto(string t, int inicio)
157	    {
158	        var nivel = 0;
159	        var enCadena = false;
160	        for (var k = inicio; k < t.Length; k++)
161	        {
162	            var c = t[k];
163	            if (enCadena)
164	            {
165	                if (c == (char)92) k++;
166	                else if (c == '"') enCadena = false;
167	            }
168	            else if (c == '"') enCadena = true;
169	            else if (c == '{') nivel++;
170	            else if (c == '}' && --nivel == 0) return k;
171	        }
172	        return -1;
173	    }
